// Bundle Leaflet with the app so opening a native map never needs a CDN script.
const {readFileSync,writeFileSync}=require('node:fs');
const js=readFileSync(require.resolve('leaflet/dist/leaflet.js'),'utf8').replace(/\/\/# sourceMappingURL=.*$/gm,'');
const css=readFileSync(require.resolve('leaflet/dist/leaflet.css'),'utf8');
writeFileSync('src/map/leaflet-bundle.generated.ts','// Generated by scripts/bundle-map.cjs. Leaflet 1.9.4, BSD-2-Clause.\nexport const leafletJS='+JSON.stringify(js)+';\nexport const leafletCSS='+JSON.stringify(css)+';\n');
